REVOKE ALL ON public.voucher_secrets FROM anon,authenticated; GRANT ALL ON public.voucher_secrets TO service_role;
REVOKE INSERT,UPDATE,DELETE ON public.voucher_items,public.voucher_batches FROM anon,authenticated; GRANT SELECT ON public.voucher_items,public.voucher_batches TO authenticated; GRANT ALL ON public.voucher_items,public.voucher_batches TO service_role;
CREATE OR REPLACE FUNCTION public.confirm_voucher_item(iid uuid,rid uuid,res text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN IF res NOT IN ('ok','error') THEN RAISE EXCEPTION 'invalid_result'; END IF; PERFORM pg_advisory_xact_lock(hashtext(rid::text)); UPDATE voucher_items SET state=CASE WHEN res='ok' THEN 'confirmed' ELSE 'failed' END,result=res WHERE id=iid AND router_id=rid AND state='sent' RETURNING batch_id INTO bid; IF bid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM voucher_items WHERE batch_id=bid AND state IN ('pending','sent')) THEN UPDATE voucher_batches SET state='complete' WHERE id=bid; END IF; END $$;
REVOKE ALL ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.confirm_voucher_item(uuid,uuid,text) TO service_role;